FETCH_MAX_CHARS = 30_000
MAX_FAILURES_PER_STEP = 3

PURPOSES = ["follow", "retry", "diagnose"]
STATUSES = ["pass", "docs_broken", "needs_human", "glitch", "unsure", "agent_gave_up"]
STEP_OUTCOMES = ["passed", "failed", "needs_human", "skipped", "not_reached"]

